import itertools
import random
import re

MODULUS = 998244353
DIGITS = "123"
ALPHABET = "123?"


def _bounded_int(token: str, upper: int) -> int | None:
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    digits = token.lstrip("+-").lstrip("0") or "0"
    if len(digits) > len(str(upper)):
        return None
    value = int(digits)
    if token.startswith("-"):
        value = -value
    return value if 0 <= value <= upper else None


def _parse(inp: str) -> tuple[int, int, list[str]] | None:
    lines = inp.splitlines()
    if not lines:
        return None
    header = lines[0].split()
    if len(header) != 2:
        return None
    height = _bounded_int(header[0], 200)
    width = _bounded_int(header[1], 200)
    if not height or not width or height * width > 200:
        return None
    rows = lines[1:]
    if len(rows) != height:
        return None
    if any(len(row) != width or any(cell not in ALPHABET for cell in row)
           for row in rows):
        return None
    return height, width, rows


def _format(rows: list[str]) -> str:
    return f"{len(rows)} {len(rows[0])}\n" + "\n".join(rows) + "\n"


def _edges(height: int, width: int):
    for row in range(height):
        for col in range(width):
            index = row * width + col
            if col + 1 < width:
                yield index, index + 1
            if row + 1 < height:
                yield index, index + width


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = [
        ["?"],
        ["1"],
        ["11"],
        ["1", "1"],
        ["12", "21"],
        ["123", "3?1"],
        ["1?", "??"],
        ["????", "????"],
        ["????????"],
        ["?", "?", "?", "?", "?", "?", "?", "?"],
        ["1?1"],
        ["1?2"],
        ["12?", "2?3"],
    ]
    tests = [_format(rows) for rows in cases[:n]] if n > 0 else []
    shapes = [(h, w) for h in range(1, 9) for w in range(1, 9)
              if h * w <= 8]
    while len(tests) < n:
        height, width = rng.choice(shapes)
        rows = [
            "".join(rng.choice("123???") for _ in range(width))
            for _ in range(height)
        ]
        tests.append(_format(rows))
    return tests


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    height, width = 15, 13
    fixed = set(rng.sample(range(height * width), 6))
    rows = [
        "".join(
            DIGITS[(row + col) % 3] if row * width + col in fixed else "?"
            for col in range(width)
        )
        for row in range(height)
    ]
    return [_format(["?" * 14] * 14), _format(rows)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse(inp)
    if parsed is None:
        return [("POST-1", "Input does not describe a grid within the stated bounds.")]

    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(r"[+-]?[0-9]+", tokens[0]) is None:
        return [("POST-2", "Expected exactly one integer token.")]
    answer = _bounded_int(tokens[0], MODULUS - 1)
    if answer is None:
        return [("POST-3", "Integer is outside the required residue range.")]

    height, width, rows = parsed
    cells = "".join(rows)
    unknowns = cells.count("?")
    failures = []
    if answer > 3 ** unknowns:
        failures.append(("POST-3", "Residue exceeds the number of possible completions."))

    fixed_conflict = any(
        cells[a] != "?" and cells[a] == cells[b]
        for a, b in _edges(height, width)
    )
    if fixed_conflict:
        if answer != 0:
            failures.append(("POST-4", "An edge joins two equal fixed digits."))
    elif unknowns == 0:
        if answer != 1:
            failures.append(("POST-4", "The fully fixed grid is valid."))
    elif height * width == 1 and answer != 3:
        failures.append(("POST-4", "An unknown single cell has three valid completions."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        height, width = rng.choice([(2, 3), (2, 4), (3, 2), (4, 2)])
        rows = [
            "".join(
                DIGITS[(row + col) % 3]
                if (row, col) == (0, 0)
                or ((row, col) not in ((0, width - 1), (height - 1, 0))
                    and rng.randrange(3) == 0)
                else "?"
                for col in range(width)
            )
            for row in range(height)
        ]
        transform = index % 4
        if transform == 0:
            changed = ["".join(column) for column in zip(*rows)]
        elif transform == 1:
            changed = [row[::-1] for row in rows]
        elif transform == 2:
            changed = rows[::-1]
        else:
            mapping = str.maketrans(DIGITS, rng.choice(("231", "312")))
            changed = [row.translate(mapping) for row in rows]
        pairs.append(("POST-5", "equal", _format(rows), _format(changed)))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse(inp)
    if parsed is None:
        return None
    height, width, rows = parsed
    cells = list("".join(rows))
    unknowns = [index for index, cell in enumerate(cells) if cell == "?"]
    if 3 ** len(unknowns) * len(cells) > 1_000_000:
        return None

    edges = tuple(_edges(height, width))
    count = 0
    for replacement in itertools.product(DIGITS, repeat=len(unknowns)):
        for index, digit in zip(unknowns, replacement):
            cells[index] = digit
        if all(cells[a] != cells[b] for a, b in edges):
            count += 1
    return f"{count % MODULUS}\n"
